export type TranscriptScrollReason =
  | "no_overflow"
  | "budget"
  | "step_cap"
  | "stalled"
  | "render_timeout"
  | "missing_rows"
  | null;

export interface TranscriptScrollSnapshot<Row = unknown> {
  rows: Row[];
  scrollTop: number;
  scrollHeight: number;
  clientHeight: number;
  renderedCount?: number;
  /**
   * Diagnostic estimate only (scrollHeight / row stride). It is never used to
   * declare a transcript complete.
   */
  estimatedTotalRows?: number | null;
  /**
   * Signature of the currently visible rows. It must change when the DOM
   * re-renders for a new scroll position; the sweep reads the DOM only after an
   * observed change (or reports render_timeout).
   */
  renderSignature?: string | number | null;
  /** Bottom of the last rendered row in scroll-content coordinates. */
  contentBottomPx?: number | null;
  /** Known bottom padding of the scroll container (whitespace, not content). */
  paddingBottomPx?: number | null;
  /** Full transcript-list content height when the list is not the scroller. */
  contentHeightPx?: number | null;
  /** Last rendered row bottom relative to the transcript list (list evidence). */
  lastRowBottomInListPx?: number | null;
  /** Measured row stride (diagnostic only; never proves completeness). */
  rowStridePx?: number | null;
  visibleCount?: number;
}

export interface TranscriptScrollResult<Row = unknown> {
  rows: Row[];
  complete: boolean;
  reason: TranscriptScrollReason;
  steps: number;
  elapsedMs: number;
  atBottom: boolean;
}

export interface CollectTranscriptRowsByScrollOptions<Row = unknown> {
  readSnapshot: () => TranscriptScrollSnapshot<Row> | null | undefined;
  setScrollTop: (scrollTop: number) => void;
  mergeRows?: (rows: Row[], batch: Row[]) => Row[];
  sleep?: (ms: number) => Promise<void> | void;
  now?: () => number;
  budgetMs?: number;
  stepDelayMs?: number;
  renderWaitMs?: number;
  pollDelayMs?: number;
  maxSteps?: number;
  overlapPx?: number;
  idlePasses?: number;
}

